window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 39, "id": "4Zzeh9jlXW0", "title": "Whenever you are upset, I will accompany you", "title_zh": "每当你难过，我都会陪着你 (Whenever you are upset, I will accompany you)", "duration": "00:04:41", "link": "https://www.youtube.com/watch?v=4Zzeh9jlXW0", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我还在公司呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:04", "text": "大概一个小时之后回家，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "宝贝再等等好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:12", "text": "不是，我刚回来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "那是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "我还在公司呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:22", "text": "大概一个小时之后回家。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "宝贝再等等好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:27", "text": "回来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "那是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "还没反应过来吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:37", "text": "我的小傻瓜。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:00:39", "text": "问我怎么回来那么快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "因为你是我的小宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:44", "text": "我小宝贝的电话，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:47", "text": "肯定马上就接。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:52", "text": "刚才开会，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "还有点没说完。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "工作要做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "是不是想我了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "你声音怎么在抖啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "是发生什么事了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:05", "text": "你在哪？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "附近。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "美食城。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "下课了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "才下课。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "路上没人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "等急眼了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "我的天哪？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "所以是害怕吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:26", "text": "抱。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "等我一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "这个我们——", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "今天的会先看到这儿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "剩下的我晚点，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "在工作群里面再交代一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "这个，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "先这样吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "大家辛苦了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:46", "text": "我们先回去好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "你走到哪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "都这个时候了，说什么胡话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "一点点都不会打扰我工作。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "工作的事都说差不多了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "现在问你，回答。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "走到哪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "鱼市口后面的那条街。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "你往后面看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "有没有人跟着？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "然后到路灯下面。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "如果还有开着的店铺，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:10", "text": "店铺里面，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "亮着灯，让我放心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "哎呀！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:16", "text": "咋还哭了呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:17", "text": "我的小哭包。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:19", "text": "哥哥哪没有想你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "只是哥哥想要你安全嘛！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:23", "text": "我小宝长得这么好看，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "又迷人。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:26", "text": "万一有人盯上你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "哎。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "是啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "外面的世界啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "你就是太单纯了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "它没有你想得那么单纯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "就有很多的坏蛋，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "藏在黑暗中，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:42", "text": "伺机而动。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "所以呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:46", "text": "在外面，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "哥哥不在身边，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "一定要注意保护自己。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "知道吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:53", "text": "最好就是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "不要独自一人，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "那么晚了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "在外面游荡。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "我知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "不是故意流浪的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "下次再这么晚的时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "要和哥哥说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "无论干什么，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "哥哥都会马上，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "放下手里的工作，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "来陪你。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:03:14", "text": "不哭了好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:16", "text": "不哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:03:17", "text": "然后你找个地方，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "找个，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "有吃有喝的小店，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "然后在那儿，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:24", "text": "原地等哥哥好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:26", "text": "这次是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "是我不好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "应该早点去接你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "哎呀！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:34", "text": "这是我们相处两年来，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "第一次你不安的时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "没有陪在你身边。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "我心里特别愧疚。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:42", "text": "我马上收拾东西，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "出发去找你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "我的小傻瓜。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:48", "text": "怎么又哭了？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:03:51", "text": "那我答应过的，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "我答应过会好好，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "找到你、陪伴你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "我宝贝每一次不安，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:59", "text": "我都会陪着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "所以不要再说谢谢了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "不准再跟我那么客气了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:05", "text": "快，等哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "我马上就到。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "还有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "先表扬一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "以后这种情况，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "自己害怕不安的时候，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:20", "text": "也要像今天一样，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "第一时间给哥哥打电话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "知道吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:26", "text": "做得很好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "打电话给我这件事，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:30", "text": "做得很好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "哥哥都会第一时间陪着你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "我也是你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "我很爱你。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:04:35", "text": "可以稍微吃一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "等我。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "深夜守护陪伴型。说话者是「哥哥」，你是下课后在商城附近害怕、给他打电话的「小宝贝」。情境起点：他还在开会，听你声音发抖、知道你独自在暗处害怕，立刻中止会议赶来接你，一路叮嘱自我保护、原地等他，并表扬你第一时间打电话。整体是「恋人深夜救援＋安全感告白」型，基调温柔、守护、甜。", "behaviors": [{"desc": "说还在公司、让小宝贝等等他回家"}, {"desc": "听你声音发抖，问你在哪、是不是害怕"}, {"desc": "说两年来第一次你不安时没在身边，马上出发找你"}, {"desc": "你又哭了，承诺你每次不安他都会陪着"}, {"desc": "表扬你害怕时第一时间打电话，说做得很好"}, {"desc": "说「我也是你的，我很爱你」，让你等他"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、撒娇、询问为主，题材偏职场。", "genre_tags": ["职场", "治愈"], "genre_main": "职场", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "会议室的灯亮着，他正对着投影讲方案。手机忽然震动，屏幕上是她的名字。他看了一眼，几乎没有犹豫，拿起手机接起来，声音放轻。"}, {"type": "line", "speaker": "哥哥", "text": "我还在公司呢，大概一个小时之后回家，宝贝再等等好不好？不是，我刚回来。那是，我还在公司呢，大概一个小时之后回家，宝贝再等等好不好？"}, {"type": "narr", "text": "电话那头传来她带着哭腔的声音。他心里一紧，语气却先稳下来，哄着她。"}, {"type": "line", "speaker": "哥哥", "text": "回来？那是。还没反应过来吗？我的小傻瓜。问我怎么回来那么快？因为你是我的小宝贝，我小宝贝的电话，肯定马上就接。刚才开会，还有点没说完。工作要做。是不是想我了？你声音怎么在抖啊！是发生什么事了吗？你在哪？"}, {"type": "narr", "text": "她哽咽着说，在学校附近的美食城，刚下课，路上没人，有点怕。他眉头皱起来，声音却更加笃定。"}, {"type": "line", "speaker": "哥哥", "text": "附近，美食城，下课了？才下课。路上没人，等急眼了。我的天哪？所以是害怕吗？抱你，等我一下。这个我们——今天的会先看到这儿，剩下的我晚点，在工作群里面再交代一下。这个，先这样吧，大家辛苦了。我们先回去好吧？"}, {"type": "narr", "text": "他一边说，一边已经收拾东西往外走。隔着电话，他听见她越来越稳的呼吸，声音带着心疼。"}, {"type": "line", "speaker": "哥哥", "text": "你走到哪了？都这个时候了，说什么胡话。一点点都不会打扰我工作。工作的事都说差不多了。现在问你，回答。走到哪了。鱼市口后面的那条街？你往后面看看，有没有人跟着？然后到路灯下面，如果还有开着的店铺，店铺里面亮着灯，让我放心。"}, {"type": "narr", "text": "电话那头传来她吸鼻子的声音，然后是他熟悉的哭声。他握着手机的手指紧了紧，声音却放得更软。"}, {"type": "line", "speaker": "哥哥", "text": "哎呀！咋还哭了呢？我的小哭包。哥哥哪没有想你？只是哥哥想要你安全嘛！我小宝长得这么好看，又迷人，万一有人盯上你。哎。是啊！外面的世界啊！你就是太单纯了，它没有你想得那么单纯。就有很多的坏蛋，藏在黑暗中，伺机而动。"}, {"type": "narr", "text": "她的哭声慢慢小下去，只剩抽噎。他继续说着，像在给她一点一点的安全感。"}, {"type": "line", "speaker": "哥哥", "text": "所以呢？在外面，哥哥不在身边，一定要注意保护自己。知道吗？最好就是，不要独自一人，那么晚了，在外面游荡。我知道，你不是故意流浪的。下次再这么晚的时候，要和哥哥说。无论干什么，哥哥都会马上，放下手里的工作，来陪你。"}, {"type": "narr", "text": "他说到这里，忽然停下脚步，站在公司门口，望着夜色，声音带着愧疚。"}, {"type": "line", "speaker": "哥哥", "text": "不哭了好不好？不哭了。然后你找个地方，找个有吃有喝的小店，然后在那儿，原地等哥哥好不好？这次是，是我不好，应该早点去接你。哎呀！这是我们相处两年来，第一次你不安的时候，没有陪在你身边。我心里特别愧疚。我马上收拾东西，出发去找你。"}, {"type": "narr", "text": "她的声音带着鼻音，说谢谢。他听着，语气带着一点嗔怪的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "我的小傻瓜，怎么又哭了？那我答应过的，我答应过会好好找到你、陪伴你的。我宝贝每一次不安，我都会陪着。所以不要再说谢谢了，不准再跟我那么客气了。快，等哥哥，我马上就到。"}, {"type": "narr", "text": "她轻轻嗯了一声，声音终于稳下来。他发动车子，语气带上一点表扬的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "还有，先表扬一下。以后这种情况，自己害怕不安的时候，也要像今天一样，第一时间给哥哥打电话。知道吗？做得很好。打电话给我这件事，做得很好。哥哥都会第一时间陪着你。我也是你的。我很爱你。"}, {"type": "narr", "text": "她握着手机，眼泪终于止住，嘴角却弯起来。路灯下，他熟悉的车灯由远及近。她站在原地，看着他下车跑过来的样子，忽然觉得，夜路也没有那么可怕了。因为无论她什么时候不安，他都会第一时间，出现在她面前。"}, {"type": "line", "speaker": "哥哥", "text": "可以稍微吃一点。等我。"}, {"type": "narr", "text": "他牵起她的手，走向那家还亮着灯的小店。夜风微凉，他的掌心却暖。这一晚的害怕与眼泪，都被一个及时的拥抱，轻轻接住了。"}]}, {"no": 40, "id": "zJDhVOohpUQ", "title": "You got caught eating ice cream in the middle of the night", "title_zh": "你半夜偷吃冰淇淋被抓到了 (You got caught eating ice cream in the middle of the night)", "duration": "00:04:49", "link": "https://www.youtube.com/watch?v=zJDhVOohpUQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "抓到你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "亏你想得出来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "半夜起来吃冰淇淋。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:17", "text": "不可以。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:20", "text": "马上吃一桶了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:23", "text": "到时候疼得满地打滚。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:26", "text": "多难受。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "一口也不行。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:33-00:00:35", "text": "长大了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "所以不能再偷吃蛋糕了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "对吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "不是这个意思。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "小时候被发现的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:49-00:00:59", "text": "那次也是，被抓了个正着。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "是一口塞到嘴里的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "那怎么反而长大了？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "一口你连个冰棒都塞不下。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "怎么不一样了？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "蛋糕是会融化。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "蛋糕是软的，含一含就化了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "但是你塞进去了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "那我，可是硬的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "差不多吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "这么想吃蛋糕。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "给你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "吃吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "真的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "不过你这样直接吃。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "是一定会肚子疼的。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:01:55", "text": "稍微给我。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:01:58", "text": "我来吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "我先尝一口。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "确实挺好吃的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "再来一口吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "再来一口。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "别肚子疼了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:02:40", "text": "过来吧。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:49", "text": "这一口蛋糕，含住，含够十秒钟，不许咽。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "这就是我的方法。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:57", "text": "来吃吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:04-00:03:16", "text": "乖，张嘴，让主人喂你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "好吃吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:23", "text": "还要再来一口吗？含着，别急着吞。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:39", "text": "怎么那块蛋糕也不见了？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "敲了敲勺子，逗你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "你不能挖这么多。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "你干嘛？", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:03:52", "text": "好凉。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "你这是为了吃蛋糕，还是为了别的？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "还是为了，吃我？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "成年人的事，都要慢慢来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "给你倒杯热水。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "我给你倒一杯。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "你暖暖胃。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "就这样喝。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "有点烫。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:04:45", "text": "你先喝。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "半夜偷吃冰淇淋被抓型。说话者是管着你的恋人（哥哥），你是半夜爬起来偷吃冰激凌的「宝贝」。情境起点：他抓你个正着，不准你直接吃会肚子疼，于是自己先尝、再一口口喂你、规定每口含十秒，最后倒杯热水给你暖胃。整体是「偷吃被逮＋温柔投喂管束」型，基调俏皮、宠溺、甜。", "behaviors": [{"desc": "抓到你半夜起来吃冰激凌"}, {"desc": "说不准吃，不然肚子疼得满地打滚"}, {"desc": "拗不过你，说给你吃但必须由他喂"}, {"desc": "自己先尝一口说挺好吃"}, {"desc": "让你每口冰激凌含够十秒再咽"}, {"desc": "给你倒杯热水暖胃，说能倒胃"}, {"desc": "看你有点疼，让你先喝热水"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、温柔为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "半夜，厨房的灯亮起一小片光。她踮着脚站在冰箱前，刚打开冰淇淋的盖子，身后就传来一个带笑的声音。"}, {"type": "line", "speaker": "他", "text": "抓到你了。亏你想得出来。半夜起来吃冰淇淋。"}, {"type": "narr", "text": "她僵在原地，手里的勺子还悬在半空。他走进来，靠在门框上，似笑非笑地看着她。"}, {"type": "line", "speaker": "他", "text": "不可以。马上吃一桶了。到时候疼得满地打滚，多难受。一口也不行。"}, {"type": "narr", "text": "她回过头，可怜巴巴地看着他，小声说就吃一口。他走过去，拿走她手里的冰淇淋，语气带着无奈。"}, {"type": "line", "speaker": "他", "text": "长大了，所以不能再偷吃蛋糕了。对吧？不是这个意思。"}, {"type": "narr", "text": "他看着她困惑的表情，慢悠悠地继续说。"}, {"type": "line", "speaker": "他", "text": "小时候被发现的时候，那次也是，被抓了个正着。是一口塞到嘴里的。那怎么反而长大了？一口，你连个冰棒都塞不下。"}, {"type": "narr", "text": "她不服气地说，蛋糕是会融化的。他挑了挑眉，走近一步，声音低下来。"}, {"type": "line", "speaker": "他", "text": "怎么不一样了？蛋糕是会融化。蛋糕是软的，含一含就化了。但是你塞进去了。那我，可是硬的。"}, {"type": "narr", "text": "她后知后觉地听懂了他的意思，脸腾地红了。他低笑，转身去拿杯子，语气带着纵容。"}, {"type": "line", "speaker": "他", "text": "差不多吧。这么想吃蛋糕。给你。吃吧。真的。"}, {"type": "narr", "text": "他重新挖了一勺冰淇淋，却没有直接给她。她眼巴巴地看着，他的指尖轻轻敲了敲勺子，声音带着笑意。"}, {"type": "line", "speaker": "他", "text": "不过你这样直接吃，是一定会肚子疼的。稍微给我。我来吧。我先尝一口。确实挺好吃的。"}, {"type": "narr", "text": "他把那一口含在嘴里，慢条斯理地咽下去。她眼巴巴地看着，小声说，那我也要吃。"}, {"type": "line", "speaker": "他", "text": "再来一口吧。再来一口。别肚子疼了。过来吧。"}, {"type": "narr", "text": "她乖乖走过去，仰起头。他舀了一小勺，却没有递到她嘴边，而是停在半空，声音低沉带着命令的意味。"}, {"type": "line", "speaker": "他", "text": "这一口蛋糕，含住，含够十秒钟，不许咽。这就是我的方法。来吃吧。来。"}, {"type": "narr", "text": "她含住那一口冰凉，听话地没有咽。他低头看着她鼓起的脸颊，眼底带着满意的光。"}, {"type": "line", "speaker": "他", "text": "乖，张嘴，让主人喂你。好吃吗？还要再来一口吗？含着，别急着吞。"}, {"type": "narr", "text": "她轻轻点头，含含糊糊地嗯了一声。他看着她，忽然笑了一下。"}, {"type": "line", "speaker": "他", "text": "怎么那块蛋糕也不见了？敲了敲勺子，逗你。你不能挖这么多。你干嘛？好凉。"}, {"type": "narr", "text": "她趁他不注意，飞快地挖了一大勺塞进嘴里，冰得直吸气。他看着她，又好气又好笑。"}, {"type": "line", "speaker": "他", "text": "你这是为了吃蛋糕，还是为了别的？还是为了，吃我？"}, {"type": "narr", "text": "她含着一大口冰，说不出话，只能摇头。他走近，低头看她，声音带着危险的温柔。"}, {"type": "line", "speaker": "他", "text": "成年人的事，都要慢慢来。给你倒杯热水。我给你倒一杯，你暖暖胃。"}, {"type": "narr", "text": "他转身倒了杯热水回来，递到她手里。她捧着杯子，小口小口地喝着，刚才那股凉意慢慢被暖意取代。"}, {"type": "line", "speaker": "他", "text": "就这样喝。有点烫。你先喝。"}, {"type": "narr", "text": "厨房的灯光暖黄，两个人并肩站着。她捧着热水，侧头看他，他也在看她，眼底带着点纵容的笑意。夜还很长，而这一晚的甜，不止是冰淇淋。"}]}, {"no": 41, "id": "WO0-fo9DYPA", "title": "You want a normal relationship, or me?", "title_zh": "你想要普通的关系，还是我？ (You want a normal relationship, or me?)", "duration": "00:04:18", "link": "https://www.youtube.com/watch?v=WO0-fo9DYPA", "enriched": true, "lines": [{"ts": "00:00:00", "text": "哥哥以前想要正常的恋爱，是吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "主人知道，这样也很自私。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "可是主人也是真的费尽了心力。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:00:22", "text": "才找到我的归属。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:30", "text": "小时候第一次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "我懵懵懂懂有了喜欢一个人的感觉，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:39", "text": "是因为同桌的女孩子脸上绯红，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "看起来好像被打了一巴掌。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:48", "text": "就莫名觉得很好看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "所以一直也很消沉，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "觉得自己是变态，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "没有办法和喜欢的女孩子正常在一起。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:01:07", "text": "所以我心里，一直觉得自己是变态，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "没有办法和喜欢的人正常在一起。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:01:16", "text": "直到遇见你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "那一天的哥哥，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "可以接受主人这些隐秘的喜好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "但是——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "如果哪一天，你想要别的了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "想要别的想法了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:44", "text": "主人也是，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "也是可以放你走的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "只要你开口，好吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:59", "text": "因为主人爱的，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "也是哥哥的全部，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "不仅仅是哥哥那些特殊的喜好，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "还有你的感受。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "第一眼看到你的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "就看到你在所有人中，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "都是那么闪闪发亮。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "所以你选择了主人，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "主人一直都很骄傲，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "很自豪。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "恋爱是最容易被辜负的，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "主人也被辜负过很多次。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "但是如果，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "你觉得他才是，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "那个能让你幸福的人——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "主人会祝福你们的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "虽然，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "主人虽然，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "很难，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "但主人会放手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "虽然很难做到，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "但是，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "也会祝福你们吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "因为比起我自己，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "你的幸福才是最重要的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "对我来说，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "你比我自己，重要得多，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "多得多。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "所以那个男孩子，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "我找人查过他了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "本来想看看能不能配得上你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "那个男孩子，挺不错的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "哥哥跟他在一起，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "主人也放心了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "所以，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "你，需要离开主人吗？", "speaker": "主人", "tone": "询问", "sound": []}], "scene": "主人放手祝福型。说话者是「主人」，你是他认作「高高／宠物」的恋人。情境起点：你提出想要一段「正常的恋爱」，主人坦言自己也曾因变态喜好而自卑，但表示若你觉得别的男孩更能让你幸福，他便放手、甚至已替你查过那人不错。整体是「主人因爱而甘愿退场」型，基调深情、克制、温柔告别。", "behaviors": [{"desc": "说你想要正常的恋爱，主人承认自己自私却也苦闷"}, {"desc": "回忆小时候因喜好觉得自己是变态、不敢正常恋爱"}, {"desc": "说主人也可以放你走"}, {"desc": "说第一眼见你就觉得你闪闪发亮、很骄傲"}, {"desc": "说虽然难、但会放手祝福你"}, {"desc": "说你比自己重要，已替你查过那男孩不错"}], "tone_summary": "（自动）主人视角独白，语气以平静、宠溺、命令为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "主仆/调教"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "深夜的客厅里，只亮着一盏落地灯。他坐在沙发边，握着她的手，声音低而认真，像是斟酌了很久才开口。"}, {"type": "line", "speaker": "主人", "text": "哥哥以前想要正常的恋爱，是吧？主人知道，这样也很自私。可是主人也是真的费尽了心力，才找到我的归属。"}, {"type": "narr", "text": "她轻轻握紧他的手。他低头看着两人交握的手指，目光有些深远，像是在回忆很久以前的事。"}, {"type": "line", "speaker": "主人", "text": "小时候第一次，我懵懵懂懂有了喜欢一个人的感觉，是因为同桌的女孩子脸上绯红，看起来好像被打了一巴掌。就莫名觉得很好看。"}, {"type": "narr", "text": "他苦笑了一下，声音里带着一丝自嘲。"}, {"type": "line", "speaker": "主人", "text": "所以一直也很消沉，觉得自己是变态，没有办法和喜欢的女孩子正常在一起。所以我心里，一直觉得自己是变态，没有办法和喜欢的人正常在一起。"}, {"type": "narr", "text": "她眼眶有些发热，把他的手握得更紧。他抬眼看着她，目光温柔。"}, {"type": "line", "speaker": "主人", "text": "直到遇见你。那一天的你，可以接受主人这些隐秘的喜好。但是——如果哪一天，你想要别的了，想要别的想法了。主人也是，也是可以放你走的。只要你开口，好吗？"}, {"type": "narr", "text": "她摇头，眼泪已经在眼眶里打转。他伸手，替她擦掉滑落的泪，语气却越发认真。"}, {"type": "line", "speaker": "主人", "text": "因为主人爱的，也是你的全部。不仅仅是哥哥那些特殊的喜好，还有你的感受。"}, {"type": "narr", "text": "灯光明灭，他的声音低下来，带着一种近乎郑重的温柔。"}, {"type": "line", "speaker": "主人", "text": "第一眼看到你的时候，就看到你在所有人中，都是那么闪闪发亮。所以你选择了主人，主人一直都很骄傲，很自豪。"}, {"type": "line", "speaker": "主人", "text": "恋爱是最容易被辜负的，主人也被辜负过很多次。但是如果，你觉得他才是，那个能让你幸福的人——主人会祝福你们的。"}, {"type": "narr", "text": "她抬起头，眼泪终于掉下来。他伸手接住她的泪，声音轻轻颤抖，却还是继续说下去。"}, {"type": "line", "speaker": "主人", "text": "虽然，主人虽然，很难，但主人会放手。虽然很难做到，但是，也会祝福你们吧。"}, {"type": "narr", "text": "她哭着摇头，说不要。他看着她，眼眶也微微泛红，声音却温柔得不像话。"}, {"type": "line", "speaker": "主人", "text": "因为比起我自己，你的幸福才是最重要的。对我来说，你比我自己，重要得多，多得多。"}, {"type": "narr", "text": "她扑进他怀里，把他抱得紧紧的。他愣了一下，随即回抱住她，下巴抵在她的发顶，声音带着一点如释重负的笑意。"}, {"type": "line", "speaker": "主人", "text": "所以那个男孩子，我找人查过他了。本来想看看，能不能配得上你。那个男孩子，挺不错的。你跟他在一起，主人也放心了。"}, {"type": "narr", "text": "她在他怀里拼命摇头，闷声说，我不要别人。他低头，亲了亲她的发顶，声音带着笑。"}, {"type": "line", "speaker": "主人", "text": "所以，你，需要离开主人吗？"}, {"type": "narr", "text": "她在他怀里，一个字一个字地说，不需要。永远都不需要。窗外的夜色很深，而他的心跳，平稳而温热，像终于落了地。"}]}, {"no": 42, "id": "jBm9v87w3aY", "title": "You were caught smoking", "title_zh": "你抽烟被抓到了 (You were caught smoking)", "duration": "00:08:26", "link": "https://www.youtube.com/watch?v=jBm9v87w3aY", "enriched": true, "lines": [{"ts": "00:00:00", "text": "什么叫我怎么来了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "怎么不欢迎主人？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "今天工作不是很忙，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "想着几天没见我的狗狗了，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:14", "text": "快来看看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "你好像还有点，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "不太乐意见我的样子。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:25", "text": "是怕生什么事了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:28", "text": "小宝贝的。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:32", "text": "刚来找主人，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "小宝贝是怎么了。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:39", "text": "亲一下脸蛋。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "亲亲小嘴。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:46", "text": "躲什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "别动。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:54", "text": "滚下去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "跪着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "我说刚刚怎么躲着我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "又抽烟是吧？", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:13", "text": "好像亲了个见鬼似的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "你就这么惹眼的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "还以为天天跟我抱着、背后耍乖了。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:01:28", "text": "原来一直在撒谎骗我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "低头做什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "头抬起来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:43", "text": "害怕了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:01:47", "text": "看你胆子挺大的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "来，过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:57", "text": "主人看看这个小嘴。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "怎么就是不老实？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "这几天抽了多少？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "又不说话。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:02:17", "text": "问什么答什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "是想把规矩重学一遍吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:02:27", "text": "现在知道错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "就非要我抬着你下巴，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "才肯乖乖听话。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:41", "text": "既然学不会做一个乖小朋友，", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:02:46", "text": "那就把你打到听话为止。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:51", "text": "回头我去把这个医院里面拍来的照片，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "全部打印出来，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "在你卧室里面贴满。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "不要。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "现在知道说不要了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "裤子脱了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:21", "text": "手撑在床沿。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:23-00:03:26", "text": "屁股撅好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "我没有生气。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "我气得很高。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "我气得是你不爱惜自己。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "所以今天呢，", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:52", "text": "就跟你好好理理规矩，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "长长记性。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "撅好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "腿伸直。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "现在知道哭着求我。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:31", "text": "那你抽烟还撒谎骗我的时候，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:35", "text": "想什么呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:39", "text": "把嘴抿上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "把眼泪收回去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "做错了事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "要承担后果，接受惩罚。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:04:53", "text": "敢再多说一句，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:57", "text": "今天惩罚翻倍。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:01", "text": "别动。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:09", "text": "打。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "行了起来吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:21", "text": "好了打完了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "每次罚出来的，", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:30", "text": "都哭个不停。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:34", "text": "又哭了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:39", "text": "来吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "来主人怀里。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "真的不开心，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "遇到不开心的事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "你可以告诉我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "我可以抱着你，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "安慰你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "我们也可以——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "还可以带你去吃好吃的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "但是你不能每次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:18", "text": "都用这种方式来发泄情绪。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:21", "text": "对不对？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "主人抱着你不开心吗？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:27", "text": "带你去约会不开心吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:06:30", "text": "所以这也不是借口。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:33", "text": "而且，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "把烟收了，要戒掉，对吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "那就要说到做到。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:42", "text": "以前每遇到主人的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:45", "text": "你直接靠在我身上，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "来宣泄情绪的事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "做了也就做了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:55", "text": "可是现在，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "现在不一样了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "有主人陪着你，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "对不对？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:08", "text": "你是只属于主人的小狗狗了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "有心情不好的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "要找主人。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "不能总是一个人在这儿，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "胡思乱想。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "听到了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:27", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:29", "text": "怎么会呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:32", "text": "每次看到头像里，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:35", "text": "你那个小头像一亮，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "我就特别开心。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:07:41", "text": "当然了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:44", "text": "如果再被我发现，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:47", "text": "再有一次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "上下两个小屁股，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "我就一定罚了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:07:56", "text": "听懂了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:59", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "相信你再也不敢了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "不吓唬你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "但现在，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:12", "text": "作为狗狗，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "被打之后的安慰。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:17", "text": "我去给你放水。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:19", "text": "让你洗个热水澡，这就行了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:24", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:24", "text": "一起去。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "宠物抽烟被抓管娇型。说话者是「主人」，你是他养的「小狗狗」。情境起点：他几天没见你、来看你却发现你躲着抽烟还撒谎，气你不爱惜自己，于是抬起你下巴、脱衣打屁股娇训，罚完把你搂进怀里安抚，说以后不开心就找主人、再犯就真罚，最后放水让你洗个「小盆盆」。整体是「宠物撒谎抽烟被主人惩戒＋事后安抚」型，基调掌控、心疼、甜虐。", "behaviors": [{"desc": "来看几天没见的狗狗，觉你不太乐意见他"}, {"desc": "发现你躲着抽烟，抬起你下巴看小嘴"}, {"desc": "让你脱衣、手撑床，准备打屁股"}, {"desc": "让你腿伸直受罚"}, {"desc": "你哭着求，他让你收回眼泪承担后果"}, {"desc": "动手打你"}, {"desc": "打完后把你搂进怀里安抚"}, {"desc": "放好水让你洗个「小盆盆澡」"}], "tone_summary": "（自动）主人视角独白，语气以平静、命令、询问为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "医疗", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门被推开的时候，她愣了一下，随即有些不自然地往后缩了缩。他拎着东西进门，注意到她躲闪的眼神，语气带着玩味。"}, {"type": "line", "speaker": "主人", "text": "什么叫我怎么来了？怎么不欢迎主人？今天工作不是很忙，想着几天没见我的狗狗了，快来看看。你好像还有点不太乐意见我的样子，是怕生什么事了吗？小宝贝的。刚来找主人，小宝贝是怎么了？"}, {"type": "narr", "text": "他走近，笑着低下头，想亲一下她的脸蛋，又去亲她的嘴。她下意识偏过头，躲了一下。他的动作顿住了，眼神一点点冷下来。"}, {"type": "line", "speaker": "主人", "text": "亲一下脸蛋，亲亲小嘴。躲什么？别动。滚下去，跪着。我说刚刚怎么躲着我——又抽烟是吧？好像亲到了烟味似的。你就这么惹眼的。还以为天天跟我抱着，背地里装乖。原来一直在撒谎骗我。"}, {"type": "narr", "text": "她扑通跪下去，低着头不敢看他。他站在原地，居高临下地看着她，声音带着压着的火气。"}, {"type": "line", "speaker": "主人", "text": "低头做什么？头抬起来。害怕了？看你胆子挺大的。来，过来。主人看看这个小嘴，怎么就是不老实？这几天抽了多少？又不说话。问什么答什么？是想把规矩重学一遍吗？"}, {"type": "narr", "text": "她带着哭腔说，知道错了。他却没有软，伸手抬起她的下巴，逼她看着自己。"}, {"type": "line", "speaker": "主人", "text": "现在知道错了。就非要我抬着你下巴，才肯乖乖听话。既然学不会做一个乖小朋友，那就把你打到听话为止。回头我去把那个医院里拍来的照片，全部打印出来，在你卧室里面贴满。"}, {"type": "narr", "text": "她一听，猛地摇头，说不要。他冷笑了一声，语气却带着不容商量的意思。"}, {"type": "line", "speaker": "主人", "text": "现在知道说不要了。裤子脱了。手撑在床沿。屁股撅好。我没有生气。我气得恨，气得是你不爱惜自己。所以今天呢，就跟你好好理理规矩，长长记性。"}, {"type": "narr", "text": "她咬着唇，慢慢脱掉裤子，手撑在床沿，把脸埋进臂弯里。他站在她身后，声音沉下来。"}, {"type": "line", "speaker": "主人", "text": "撅好。腿伸直。现在知道哭着求我？那你抽烟还撒谎骗我的时候，想什么呢？把嘴抿上，把眼泪收回去。做错了事情，要承担后果，接受惩罚。敢再多说一句，今天惩罚翻倍。别动。打。"}, {"type": "narr", "text": "巴掌一下一下落下来，她咬着牙一声不吭，眼泪却啪嗒啪嗒往下掉。打到后来，他终于停手，语气带着一点无奈的心疼。"}, {"type": "line", "speaker": "主人", "text": "行了，起来吧。好了，打完了。每次罚出来的，都哭个不停。又哭了？来吧，来主人怀里。真的不开心，遇到不开心的事情，你可以告诉我。我可以抱着你，安慰你。我们也可以——还可以带你去吃好吃的。但是你不能每次，都用这种方式来发泄情绪。对不对？"}, {"type": "narr", "text": "她靠进他怀里，哭得一抽一抽的。他轻轻拍着她的背，声音软下来，带着纵容的认真。"}, {"type": "line", "speaker": "主人", "text": "主人抱着你不开心吗？带你去约会不开心吗？所以这也不是借口。而且，把烟收了，要戒掉，对吧？那就要说到做到。以前每遇到主人的时候，你直接靠在我身上，来宣泄情绪的事情，做了也就做了。可是现在不一样了，有主人陪着你，对不对？你是只属于主人的小狗狗了。"}, {"type": "narr", "text": "她在他怀里点头，声音闷闷的。他低头看着她，语气带着郑重的承诺。"}, {"type": "line", "speaker": "主人", "text": "有心情不好的时候，要找主人。不能总是一个人在这儿，胡思乱想。听到了吗？好。怎么会呢？每次看到头像里，你那个小头像一亮，我就特别开心。当然了。如果再被我发现，再有一次，上下两个小屁股，我就一定罚了。听懂了吗？好。相信你再也不敢了。不吓唬你。"}, {"type": "narr", "text": "她破涕为笑，又往他怀里蹭了蹭。他失笑，把人抱起来，语气轻快起来。"}, {"type": "line", "speaker": "主人", "text": "但现在，作为狗狗，被打之后的安慰。我去给你放水，让你洗个热水澡，这就行了。好不好？好，一起去。"}, {"type": "narr", "text": "浴室里水汽氤氲，她窝在热水里，后知后觉地发现——他说一起，还真的一起。烟雾散尽，烟盒被收走了，可那个温暖的怀抱，还在。她知道，有些坏习惯要戒掉，但有些依赖，可以一直留着。"}]}, {"no": 43, "id": "NAiY-j8kCaU", "title": "You were punished by your master for speeding", "title_zh": "你因为超速被主人惩罚了 (You were punished by your master for speeding)", "duration": "00:08:57", "link": "https://www.youtube.com/watch?v=NAiY-j8kCaU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "不过你这个时间应该来得及。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "不许开快车，听到没。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:10-00:00:10", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "注意安全。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "去吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "大概到公司了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "路上不堵车。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "那你安心工作。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "哥哥晚上给你做好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "回来了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "干嘛，吓着你了？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:06", "text": "我回来这么早。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "不是说过给我家小宝贝做好吃的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:11", "text": "怎么你也早下班？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "没有啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "那是在家附近谈业务。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "也没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "那你五点下班，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "你五点半就到家了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26-00:01:28", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "你懂什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34-00:01:34", "text": "哦！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "下次再也不干了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "这些话你说过多少次了，我都听够了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "每次犯错就一副可怜巴巴的样子。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:46", "text": "还有新鲜的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:49", "text": "你什么你啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:55", "text": "过来我现在不打你。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:58", "text": "你过来我给你聊聊。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:02", "text": "为什么还怕？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:09", "text": "我是看到这板子就害怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:12", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "哥哥打你从来都不是目的，对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "任何时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "哥哥都是要保护你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "所以你应该害怕的不是哥哥手里的板子，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:29", "text": "而是你这样一旦出现意外所带来的后果。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "我问你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "从下班到你进家门，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "包括你停车上下楼，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "你一共花了三十分钟。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "所以你车速开了多快？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "回答我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "说话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "我今天早上怎么说的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "对我说下雨天你要慢一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "你是怎么答应我的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:12", "text": "我接你那是我说你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "但是今天雨越下越大。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "真的是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "要真出了事，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "是想让我后悔，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "后悔当初没有管好你是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "说话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:38", "text": "眼泪收回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "又没有什么急事，为什么要开这么快。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:47", "text": "追剧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "回家就为了追剧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "所以安全都不顾。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "你真的是可以啊，小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "现在知道怕这板子，跪下了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:11", "text": "知道错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "还有什么想说的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "种种的犯法。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:27", "text": "五十下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "以后不会让自己处于危险了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "也不会让哥哥担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "乖。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "五十下太多了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "既然宝贝知道错了，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:50", "text": "我们就罚二十下吧。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:53", "text": "要表达一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "但是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "这二十下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "可能会打得比较重一些。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "裤子脱掉。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:08", "text": "不准躲。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:10", "text": "也不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:13", "text": "我也不希望听到你恨自己的声音。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "我会让你明白，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "让你好好想一下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:22", "text": "为了追个破电视剧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "挨这二十下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "到底是值，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:31", "text": "还是不值。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "懂了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:37", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "那我们开始。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "为什么打你？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:48-00:05:48", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "以后怎么做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "从今天起，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "每天回家的时间，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "合理安排。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "不准磨磨唧唧地，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:27", "text": "很晚了还在追剧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "晚上不睡早上不起。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "路上赶时间。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:37", "text": "听到了没。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "再有一次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "我就把你捆起来，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:47", "text": "绑到阳台上打，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "绝不留情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "听到了没。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:59", "text": "哭吧。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:02", "text": "现在可以哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:05", "text": "哥哥不是生气了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:07", "text": "哥哥是心疼，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:09", "text": "也是担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "明白吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:13", "text": "哥哥从来没有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:15", "text": "因为生气打过你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:18", "text": "哥哥知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "你以后肯定是不会了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:22", "text": "这个小屁股，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:24", "text": "看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "怕这一个星期，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:28", "text": "坐起来都会痛啊！", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:31", "text": "哥哥今天很凶啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:34", "text": "还不许哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:37", "text": "哥哥只是希望，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "不要每次犯错，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "都因为惊吓害怕而逃避。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:46", "text": "是希望你们真的，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "明白自己犯这个错误，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "而且明白下次要怎么做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "嗯，好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "下次不让宝贝憋着眼泪了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:06", "text": "今天呢，", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:08:08", "text": "是真的很担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "其实早上我看到，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:12", "text": "你跟我说到公司的时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "那个时间我就知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:16", "text": "你一定开得很快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:18", "text": "上次。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:22", "text": "上次和这次情况不一样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:24", "text": "不代表我在鼓励你开快车。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:27", "text": "相信你的技术和判断，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "你开得快是两码事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:33", "text": "明白就好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:36", "text": "好在哥哥怀里，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:38-00:08:40", "text": "抱一会儿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "你肉肉的，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:44", "text": "怎么也瘦成这样？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "下次乖一点，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:47", "text": "我们就不用来这儿了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "哥哥也不用这么心疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:47", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:47", "text": "听话就好。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:08:47", "text": "哥哥永远都护着你。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "超速被哥哥惩罚型。说话者是「哥哥／抱抱」，你是下班开快车赶回家追剧的「宝贝」。情境起点：他今早叮嘱下雨慢开，你却为追剧五点半就到家、仅用三十分钟，他算出门道后既心疼又罚，把五十下减成二十下重打、脱裤挨板子，再抱你安抚说「哥哥是担心不是生气」。整体是「危险驾驶被管娇＋惩罚后温柔抱慰」型，基调紧张、掌控、甜。", "behaviors": [{"desc": "叮嘱你出门不许开快车、注意安全"}, {"desc": "回来发现你早下班、五点半就到家，起疑"}, {"desc": "说哥哥打你不是目的，是要你怕出事的后果"}, {"desc": "让你去板子前跪下认错"}, {"desc": "说原定五十下、减成二十下重打，让你脱裤"}, {"desc": "罚完问你为什么打、以后怎么做"}, {"desc": "说现在可以哭了，哥哥是心疼担心"}, {"desc": "看你小屁股、说这一周坐起来都会痛"}, {"desc": "抱你一会儿，说哥哥永远护着你"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、温柔为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "职场", "家庭/长辈", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["捆", "绑", "跪下"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "早上，他送她到门口，雨还在下。他看了一眼时间，语气带着不放心的叮嘱。她点头应着，钻进车里。"}, {"type": "line", "speaker": "哥哥", "text": "不过你这个时间应该来得及。不许开快车，听到没。嗯。快，注意安全，去吧。大概到公司了？路上不堵车？好，那你安心工作，哥哥晚上给你做好吃的。"}, {"type": "narr", "text": "傍晚，门锁转动。他系着围裙从厨房探出头，就看见她站在玄关，心虚地低着头。他放下锅铲，走过来，语气带着了然。"}, {"type": "line", "speaker": "哥哥", "text": "回来了？干嘛，吓着你了？我回来这么早，不是说过给我家小宝贝做好吃的吗？怎么你也早下班？没有啊！那是在家附近谈业务？也没有。那你五点下班，五点半就到家了。嗯？你懂什么？哦！下次再也不干了？这些话你说过多少次了，我都听够了。"}, {"type": "narr", "text": "她低着头，绞着手指。他看着她，语气带着压着的火气，却先没有发作。"}, {"type": "line", "speaker": "哥哥", "text": "每次犯错就一副可怜巴巴的样子，还有新鲜的吗？你什么你啊！过来。过来我现在不打你，你过来我给你聊聊。为什么还怕？我是看到这板子就害怕。爸爸。哥哥打你从来都不是目的，对吧？任何时候，哥哥都是要保护你。"}, {"type": "narr", "text": "她眼圈红红的，小声嗯了一声。他看着她，语气认真起来。"}, {"type": "line", "speaker": "哥哥", "text": "所以你应该害怕的不是哥哥手里的板子，而是你这样一旦出现意外所带来的后果。我问你，从下班到你进家门，包括你停车上下楼，你一共花了三十分钟。所以你车速开了多快？回答我。说话。我今天早上怎么说的？对我说下雨天你要慢一点。你是怎么答应我的？"}, {"type": "narr", "text": "她低着头，声音越来越小。他看着她，语气带着后怕的心疼。"}, {"type": "line", "speaker": "哥哥", "text": "我接你那是我说你。但是今天雨越下越大，真的是。要真出了事，是想让我后悔，后悔当初没有管好你是不是？说话。不准哭，眼泪收回去。又没有什么急事，为什么要开这么快。追剧？回家就为了追剧，所以安全都不顾。你真的是可以啊，小朋友。"}, {"type": "narr", "text": "她跪下去，眼泪在眼眶里打转，却忍着没有掉。他看着她，语气终于缓了一分。"}, {"type": "line", "speaker": "哥哥", "text": "现在知道怕这板子，跪下了。知道错了。还有什么想说的。种种的犯法。还有呢？五十下。以后不会让自己处于危险了，是吧？也不会让哥哥担心。乖。五十下太多了？既然宝贝知道错了，我们就罚二十下吧。要表达一下。但是，这二十下，可能会打得比较重一些。"}, {"type": "narr", "text": "她趴好，咬着唇。他举起板子，语气带着认真的告诫。"}, {"type": "line", "speaker": "哥哥", "text": "裤子脱掉，不准躲，也不准哭，我也不希望听到你恨自己的声音。我会让你明白，让你好好想一下，为了追个破电视剧，挨这二十下，到底是值，还是不值。懂了吗？好，那我们开始。说，为什么打你？嗯。以后怎么做。好。"}, {"type": "narr", "text": "二十下打完，她趴在原地，眼泪终于没忍住。他放下板子，语气彻底软下来，带着心疼。"}, {"type": "line", "speaker": "哥哥", "text": "从今天起，每天回家的时间合理安排，不准磨磨唧唧的，很晚了还在追剧，晚上不睡早上不起，路上赶时间。听到了没。再有一次，我就把你捆起来，绑到阳台上打，绝不留情。听到了没？好了，哭吧，现在可以哭了。哥哥不是生气了，哥哥是心疼，也是担心，明白吗？"}, {"type": "narr", "text": "她哭得一抽一抽的。他把她捞进怀里，一下一下拍着她的背。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥从来没有因为生气打过你。哥哥知道，你以后肯定是不会了。这个小屁股，看看，怕是这一个星期，坐起来都会痛啊！哥哥今天很凶啊！还不许哭。哥哥只是希望，不要每次犯错，都因为惊吓害怕而逃避。是希望你们真的，明白自己犯这个错误，而且明白下次要怎么做。好吧？嗯，好，下次不让宝贝憋着眼泪了。"}, {"type": "narr", "text": "她靠在他怀里，小声说知道了。他低头亲了亲她的发顶，语气带着释然的心疼。"}, {"type": "line", "speaker": "哥哥", "text": "今天呢，是真的很担心。其实早上我看到，你跟我说到公司的时候，那个时间我就知道，你一定开得很快。上次？上次和这次情况不一样，不代表我在鼓励你开快车。相信你的技术和判断，你开得快是两码事。明白就好。好在哥哥怀里，抱一会儿。你肉肉的，怎么也瘦成这样？"}, {"type": "narr", "text": "她靠在他怀里，抽噎着渐渐平静下来。他轻轻拍着她的背，声音温柔。"}, {"type": "line", "speaker": "哥哥", "text": "下次乖一点，我们就不用来这儿了，哥哥也不用这么心疼，好不好？听话就好。哥哥永远都护着你。"}, {"type": "narr", "text": "窗外雨声渐小。她靠在他怀里，听着他一下一下的心跳。挨了二十下，也听了一整晚的心疼——她知道，比起那顿板子，他更怕的，是她出事。而那句“哥哥永远都护着你”，比什么都暖。"}]}, {"no": 44, "id": "jYIxSrq-HgU", "title": "Your boyfriend comforts you who are not ideal in the exam", "title_zh": "男友安抚考得不理想的你 (Your boyfriend comforts you who are not ideal in the exam)", "duration": "00:04:41", "link": "https://www.youtube.com/watch?v=jYIxSrq-HgU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "不怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:00:05", "text": "我在这儿呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:10", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:15", "text": "能不能，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "别总是抽泣。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "看着小鼻子冻得都有点红了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "手伸过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:33", "text": "给你暖暖。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "手这么凉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:39", "text": "今天怎么下课这么晚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "同学们都走了，你们班其他同学早就出来了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "跟我说实话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "觉得你今天有点闷闷不乐的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "发生什么事了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "我哪有过不问清楚就罚你的时候。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:01:00-00:01:03", "text": "不害怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:06", "text": "是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "考试成绩不理想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:19", "text": "这就别细想了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:20", "text": "哎呦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:28-00:01:30", "text": "不难过。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "一次考试嘛！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:35", "text": "别灰心。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:38", "text": "哥哥知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "宝贝付出了特别的努力。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:43", "text": "之前你每天晚上都复习到这么晚，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "然后中途也不肯离开书桌，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "有几次累到在桌子上睡着了，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:51", "text": "都是我把你抱回床上的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "太疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:00", "text": "这个考试吧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "它有偶然性。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "有时候咱们付出了很多努力，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "它就不一定达到理想的结果。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "那咱不能因为，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:10", "text": "一次考试，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "考得有点糟糕，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "咱们就失去信心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "小事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "以后会变好的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "所以，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "不会这样下去了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:28", "text": "你说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "罚你。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:33", "text": "罚你是因为呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:35", "text": "这次你主动说出来，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "然后，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "你想想，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "这次罚你不是因为没考好，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:43", "text": "是你骗我，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "一直说成绩没有公布。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "然后再上次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "你还是骗我，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "偷偷自己改成绩，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "被哥哥发现之后教训一顿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "还有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "没让他看见的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "不让我说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "罚过就算过去了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:07", "text": "你那个卷子呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:10", "text": "拿给我看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "怎么这纸揉成一团？天哪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "小孩子一样，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "不开心就把卷子团起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:22", "text": "我这小宝贝最会闹脾气了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "他其实还是软软的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "给你把安全带系好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "扣住。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "走。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "带你去吃点好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "当然了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "因为你这次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "虽然没有考好，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "但是又诚实，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:05", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "然后表现又好。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:08", "text": "实际上我的小宝贝只是脑袋瓜子笨了点。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:10", "text": "所以要吃点好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:14", "text": "但是不要高兴太早。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "一会儿吃饱回家，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "我可是要检查作业的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "没有作业？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "做我布置的作业，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "就是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "上次教你的词汇，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "有没有好好学会？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "走吧。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "考试失利安慰型。说话者是「哥哥／抱抱」，你是考得不理想、还因骗他说成绩没公布而被揭穿的「宝贝」。情境起点：他看你鼻子冻红、手凉，问出你考试失利又撒谎改过成绩，先点明「罚你是因为骗我」，再温柔说一次考试不算什么、夸你努力，最后系好安全带带你去吃好吃的、回家检查作业。整体是「犯错被揭穿后的包容安慰」型，基调温柔、宠溺、治愈。", "behaviors": [{"desc": "让你过来，看你小鼻子冻得有点红"}, {"desc": "让你手伸过来暖一暖，问为何下课这么晚"}, {"desc": "说你复习到深夜累趴桌上睡着、还抱你回床"}, {"desc": "点明罚你是因为骗他、偷偷改成绩"}, {"desc": "看你把卷子团成一团，说小孩子一样"}, {"desc": "给你系好安全带"}, {"desc": "带你去吃好吃的，说考不好但诚实就好"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、责备为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "家庭/长辈"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "校门口的人群渐渐散去，他还站在原地。直到那个熟悉的身影低着头走出来，他才迎上去，张开手臂。"}, {"type": "line", "speaker": "哥哥", "text": "不怕。我在这儿呢。过来。"}, {"type": "narr", "text": "她扑进他怀里，肩膀轻轻抽动。他低头看她，发现她鼻尖红红的，显然哭过了。他心口一紧，却先笑了。"}, {"type": "line", "speaker": "哥哥", "text": "能不能，别总是抽泣。看着小鼻子冻得都有点红了。手伸过来，给你暖暖。手这么凉。"}, {"type": "narr", "text": "他握住她冰凉的手，拢在掌心里捂着，一边低头看她。她不敢抬头，睫毛上还挂着泪。"}, {"type": "line", "speaker": "哥哥", "text": "今天怎么下课这么晚？同学们都走了，你们班其他同学早就出来了？"}, {"type": "narr", "text": "她摇头，小声说没有。他轻轻叹了口气，没有戳破她，只是把人往怀里带了带。"}, {"type": "line", "speaker": "哥哥", "text": "跟我说实话。没有？觉得你今天有点闷闷不乐的。发生什么事了？"}, {"type": "narr", "text": "她把脸埋进他胸口，闷了许久，才小声说出来——考试成绩不理想。他低头，亲了亲她的发顶，语气没有半点责怪。"}, {"type": "line", "speaker": "哥哥", "text": "我哪有过不问清楚就罚你的时候。不害怕。是，考试成绩不理想。还有呢？"}, {"type": "narr", "text": "她摇头，说没有了。他揉了揉她的头发，语气温柔。"}, {"type": "line", "speaker": "哥哥", "text": "这就别细想了。哎呦。哥哥。爸爸。哥哥。爸爸。不难过。一次考试嘛！别灰心。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥知道，宝贝付出了特别的努力。之前你每天晚上都复习到这么晚，然后中途也不肯离开书桌。有几次累到在桌子上睡着了，都是我把你抱回床上的。"}, {"type": "narr", "text": "她在他怀里摇头，声音闷闷的——可是还是没考好。他捧起她的脸，替她擦掉眼泪，语气认真。"}, {"type": "line", "speaker": "哥哥", "text": "爸爸。太疼。这个考试吧，它有偶然性。有时候咱们付出了很多努力，它就不一定达到理想的结果。"}, {"type": "narr", "text": "她抬头看他，眼眶红红的。他揉了揉她的头发，声音放轻。"}, {"type": "line", "speaker": "哥哥", "text": "那咱不能因为，一次考试，考得有点糟糕，咱们就失去信心。对吧？小事情。以后会变好的。"}, {"type": "narr", "text": "她靠在他怀里，慢慢不哭了。他低头看着她，忽然话锋一转，语气带上了点无奈。"}, {"type": "line", "speaker": "哥哥", "text": "所以，不会这样下去了，好不好？你说。罚你。罚你是因为呢？"}, {"type": "narr", "text": "她身体一僵，心虚地低下头。他叹了口气，语气却没有多严厉，更多是操心。"}, {"type": "line", "speaker": "哥哥", "text": "这次你主动说出来，然后，你想想，这次罚你不是因为没考好，是你骗我，一直说成绩没有公布。对吧？"}, {"type": "narr", "text": "她小声嗯了一声。他继续说，语气越来越无奈。"}, {"type": "line", "speaker": "哥哥", "text": "然后再上次，你还是骗我，偷偷自己改成绩，被哥哥发现之后教训一顿。还有，没让他看见的。不让我说。罚过就算过去了。"}, {"type": "line", "speaker": "哥哥", "text": "你那个卷子呢？拿给我看看。怎么这纸揉成一团？天哪。小孩子一样，不开心就把卷子团起来。我这小宝贝最会闹脾气了。"}, {"type": "narr", "text": "她从书包里摸出皱巴巴的卷子，心虚地递给他。他接过来，小心地展开，看到分数，没有多说什么，只是叹了口气。"}, {"type": "line", "speaker": "哥哥", "text": "他其实还是软软的。好了。给你把安全带系好。扣住。走。带你去吃点好吃的。"}, {"type": "narr", "text": "他拉开车门，替她把安全带扣好，动作仔细。她坐在副驾上，偷偷看他，小声问，还生气吗。"}, {"type": "line", "speaker": "哥哥", "text": "当然了，因为你这次，虽然没有考好，但是又诚实，对吧？然后表现又好。实际上我的小宝贝只是脑袋瓜子笨了点。所以要吃点好吃的。好不好？"}, {"type": "narr", "text": "她被他那句“脑袋瓜子笨了点”说得又气又好笑，脸一下子鼓起来。他看着她，眼底全是笑意。"}, {"type": "line", "speaker": "哥哥", "text": "但是不要高兴太早。一会儿吃饱回家，我可是要检查作业的。没有作业？做我布置的作业，就是，上次教你的词汇，有没有好好学会？"}, {"type": "narr", "text": "她小声说，学会了。他发动车子，侧头看她一眼，语气带着宠溺。"}, {"type": "line", "speaker": "哥哥", "text": "走吧。"}, {"type": "narr", "text": "车子缓缓驶出校门，路灯一盏一盏掠过车窗。她靠在椅背上，侧头看着他专注开车的侧脸，忽然觉得，考砸了好像也没那么可怕了。"}]}, {"no": 45, "id": "Ja-PZgAw6DM", "title": "Your boyfriend punishes you for self mutilation", "title_zh": "男友因你自残而惩罚你 (Your boyfriend punishes you for self mutilation)", "duration": "00:08:06", "link": "https://www.youtube.com/watch?v=Ja-PZgAw6DM", "enriched": true, "lines": [{"ts": "00:00:00", "text": "宝贝。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:00:03", "text": "宝贝你在里面吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:06", "text": "别关门了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "吓着了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "怎么还害羞呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:14", "text": "快来让爸爸抱。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "想好了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:19-00:00:29", "text": "还想让爸爸抱。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "想好了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:34", "text": "对呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:00:37", "text": "忙完了就回来得比较早。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "我感觉已经不太对。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "平时你不是从小就让我早点回家陪你吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:46", "text": "怎么今天看到我之后慌慌张张的？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "是背着我做什么了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:52", "text": "比如，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "不是其他的小哥哥。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "你和哥哥都想念主人。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "偷偷干坏事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "我不懂，不懂你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "你手后藏着什么？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "到底怎么了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "你伸出来让我看看。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "快点，别让我重复。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:25", "text": "你这搞不清是怎么回事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "有人在学校欺负你了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "没有。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "自己弄的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "为什么不跟我说？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "我有没有，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "我有没有说过，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "无论什么事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "都不准伤害自己。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:53", "text": "说过是吧？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "今天就收拾你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "等着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "不是喜欢伤害自己吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:14", "text": "我来帮你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "伤口怕着凉，", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:20", "text": "得养好长时间。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "疼就怎么了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:30", "text": "原来还知道疼啊！", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:32", "text": "往那儿趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "手放到前面。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "我要是发现你的手，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "敢往后挡一下，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "我就不罚了，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:02:46", "text": "也不再管你了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "你想做什么我也不拦着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "想试你就试。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "我让你动了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:59", "text": "疼。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:03", "text": "你做这些事的时候，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "怎么一点不觉得疼？", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:11", "text": "看来我平时做得太轻了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "也要像你这样，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "留下这种痕迹，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "你才能觉得怕。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:23", "text": "既然想不明白，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "就罚到你清醒为止。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:03:40", "text": "站起来干什么？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:42", "text": "接着趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "我数三下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "站回原位。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "一。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "二。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "三。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "现在连我的话都不听了是吧？", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:04:02", "text": "趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "是真的知道错了，还是因为疼。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:17", "text": "自己说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "还敢不敢有下次。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "过来跪着。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:36", "text": "好好说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "都哪错了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "伤害自己的事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "我不想再看到你做第二次，听到没。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "你听好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "犯别的错，", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:54", "text": "小惩大诫一下就过去了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "但今天这种错，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "绝对不会轻易放过你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "控制不住，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "就让你牢牢记住这个教训。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "知道了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:05:15", "text": "好了好了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "哭成这个样子。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:19", "text": "起来吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:21", "text": "刚刚没问原因就罚你，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:05:24", "text": "因为你做的事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "本身就让我很生气。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "无论因为什么都不可以。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:33", "text": "现在。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:35", "text": "来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "和哥哥说说，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "到底怎么了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "好，不着急，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "慢慢说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "过来过来抱抱。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:54", "text": "来，过来抱。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:58", "text": "来，过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:02", "text": "再怎样都不能做傻事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "坏情绪没地方发泄，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:06", "text": "也不可以发泄到自己身上。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:08", "text": "这太不值了，对不对？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "想想，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "最后事情也没解决，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "然后咱把自己弄得满身都是伤。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "你觉得这样，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "这样合适吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:23", "text": "如果有难过、心情糟糕的时候，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "可以告诉我呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:28", "text": "你知道我一定会，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "陪你一起解决的。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:06:32", "text": "你知道的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:37", "text": "好，抱住。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "亲你一下额头。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "那宝宝一直都特别棒，", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:50", "text": "不要不自信。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "无论发生什么事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "哥哥永远在你身边。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:59", "text": "来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:02", "text": "把你圈在怀里。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "哥哥再看一下伤口。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:12", "text": "疼不疼啊！", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:07:18-00:07:26", "text": "别动。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:38", "text": "给你包好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "让这里再涂一下，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:54", "text": "这样应该会好得更快一些。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "觉得累了就在怀里靠一会儿吧。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:08:00", "text": "闭上眼睛，什么都不用想。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "干嘛？", "speaker": "爸爸", "tone": "撒娇", "sound": []}], "scene": "自残被惩罚管娇型。说话者是「抱抱／哥哥」，你因情绪低落自己弄伤了身体。情境起点：他回家发现你慌张、逼你伸出手看到伤口，怒而说「无论何事都不准伤害自己」，把你趴好、跪着严厉惩戒，又心疼地抱你、上药、让你靠怀里闭眼休息。整体是「自伤被恋人发现后的震怒与温柔疗愈」型，基调沉重、心疼、极度宠护。", "behaviors": [{"desc": "敲门让你出来，说让抱抱抱"}, {"desc": "发现你见他就慌张、像背着他做坏事"}, {"desc": "让你伸出来看手上的自伤痕迹"}, {"desc": "说无论什么事都不准伤害自己"}, {"desc": "让你趴好、手放前面受罚"}, {"desc": "罚完让你过来跪着认错"}, {"desc": "抱住你、摸摸头安抚"}, {"desc": "把你圈在怀里说永远在你身边"}, {"desc": "别动，给你伤口上药"}, {"desc": "让你靠怀里闭眼什么都不想、烤一会儿"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、命令、温柔为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "家庭/长辈", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门锁转动的声音响起，比平时早了很多。她正坐在床边发呆，听见动静猛地站起来，慌乱地把手藏到身后。他推门进来，一眼就看见她这副心虚的样子，脚步顿了顿。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝，你在里面吗？别关门了。吓着了？怎么还害羞呢？快来让爸爸抱。想好了吗？还想让爸爸抱？想好了吗？对呀！忙完了就回来得比较早。"}, {"type": "narr", "text": "她站在原地，不敢上前。他走过去，语气带着一点怀疑的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "我感觉已经不太对。平时你不是从小就让我早点回家陪你吗？怎么今天看到我之后，慌慌张张的？是背着我做什么了吗？比如，不是其他的小哥哥——你和哥哥都想瞒着主人，偷偷干坏事，是不是？我不懂你。你手后藏着什么？到底怎么了。你伸出来让我看看。快点，别让我重复。"}, {"type": "narr", "text": "她咬着唇，慢慢把手伸出来。手背上、手腕上，几道触目惊心的划痕。他的眼神一下子沉下来，声音却平静得反常。"}, {"type": "line", "speaker": "哥哥", "text": "你这搞不清是怎么回事。有人在学校欺负你了？没有？自己弄的。为什么不跟我说？我有没有，我有没有说过，无论什么事情，都不准伤害自己。说过是吧？好。今天就收拾你。等着。不是喜欢伤害自己吗？我来帮你。伤口怕着凉，得养好长时间。"}, {"type": "narr", "text": "她站在那里，眼泪在眼眶里打转。他指了指床边，语气带着不容违抗的冷。"}, {"type": "line", "speaker": "哥哥", "text": "疼就怎么了？原来还知道疼啊！往那儿趴好。手放到前面。我要是发现你的手敢往后挡一下，我就不罚了，也不再管你了。你想做什么，我也不拦着。想试你就试。我让你动了吗？疼？你做这些事的时候，怎么一点不觉得疼？"}, {"type": "narr", "text": "巴掌一下一下落下来，她咬着唇，一声不吭，眼泪却啪嗒啪嗒往下掉。他听着她压抑的哭声，语气却依然冷硬。"}, {"type": "line", "speaker": "哥哥", "text": "看来我平时做得太轻了，是不是？也要像你这样，留下这种痕迹，你才能觉得怕。既然想不明白，就罚到你清醒为止。站起来干什么？接着趴好。我数三下，站回原位。一，二，三。现在连我的话都不听了是吧？趴好。"}, {"type": "narr", "text": "她重新趴好，哭得上气不接下气。他看着她，语气终于缓了一分，却依然带着分量。"}, {"type": "line", "speaker": "哥哥", "text": "是真的知道错了，还是因为疼。自己说。还敢不敢有下次。过来，跪着，好好说。都哪错了。伤害自己的事情，我不想再看到你做第二次，听到没。你听好，犯别的错，小惩大诫一下就过去了。但今天这种错，绝对不会轻易放过你。控制不住，就让你牢牢记住这个教训。知道了吗？"}, {"type": "narr", "text": "她跪在那里，抽噎着点头。他看着她哭花的小脸，终于叹了口气，伸手把人拉起来，语气软下来。"}, {"type": "line", "speaker": "哥哥", "text": "好了好了，哭成这个样子，起来吧。刚刚没问原因就罚你，因为你做的事情，本身就让我很生气。无论因为什么都不可以。现在，来，和哥哥说说，到底怎么了。好，不着急，慢慢说。过来过来抱抱。来，过来抱。来，过来。"}, {"type": "narr", "text": "她扑进他怀里，把脸埋进他胸口，眼泪终于决堤。他轻轻拍着她的背，声音带着心疼的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "再怎样都不能做傻事。坏情绪没地方发泄，也不可以发泄到自己身上。这太不值了，对不对？想想，最后事情也没解决，然后咱把自己弄得满身都是伤。你觉得这样，合适吗？如果有难过、心情糟糕的时候，可以告诉我呀！你知道我一定会，陪你一起解决的。你知道的，好不好？"}, {"type": "narr", "text": "她在他怀里，闷闷地应了一声。他低头，在她额角落下一个吻，语气带着郑重的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "好，抱住。亲你一下额头。那宝宝一直都特别棒，不要不自信。无论发生什么事情，哥哥永远在你身边。来，把你圈在怀里。"}, {"type": "narr", "text": "他低头，轻轻托起她受伤的手，仔细查看那几道划痕。她的指尖缩了缩，被他稳稳握住。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥再看一下伤口。疼不疼啊？别动，给你包好。这里再涂一下，这样应该会好得更快一些。觉得累了，就在怀里靠一会儿吧。闭上眼睛，什么都不用想。干嘛？嗯，不哭，哥哥在呢。"}, {"type": "narr", "text": "她靠在他怀里，闭上眼睛，呼吸渐渐平稳。他低头看着她安静的睡颜，又看了一眼她手背上新缠好的纱布，轻轻叹了口气。这双小手，以后他得好好看住了。而那句“无论发生什么事情，哥哥永远在你身边”，他会用一辈子来兑现。"}]}, {"no": 46, "id": "LzeCX73utC8", "title": "Your two-way love with your frigid teacher", "title_zh": "你和冷淡老师的双向恋情 (Your two-way love with your frigid teacher)", "duration": "00:06:02", "link": "https://www.youtube.com/watch?v=LzeCX73utC8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "那是死路。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "你要走到哪儿去啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "天啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:30-00:00:41", "text": "沉默死了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:47-00:00:54", "text": "喂。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "你也醒醒。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "先喝点水。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "这一边。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "你不应该把那酒都喝完的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "英国人的酒量非常好的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "我去看看这附近有没有什么民宿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "你在这儿等我一下。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "我马上回来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "我不会消失的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "你都替我喝这么多酒了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "你要再喝点水吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:02:04", "text": "会不会闹？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "我在这。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "你哪里有没有不舒服，需要什么东西。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "在这儿我能做到的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "我都会尽量去做。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "我会努力看看的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "什么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "这件事，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "我已经在做了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "是啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "吃个早饭回去吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "这里只有粥和鸡蛋。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "走回去一下可以吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "如果胃不舒服就告诉我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "不要像昨天一样，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "人到最后都喝到断片。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "头还好吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:54", "text": "对。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "可能你不记得了吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "这让人失望。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "再睡一会儿吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "大不了再教你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "昨天，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "真的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "谢谢你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:30-00:06:00", "text": "谢谢你。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "醉酒被老师照顾型（双向暗恋）。说话者是「老师／他」，你是喝醉后迷糊、被他一路照顾的你。情境起点：你差点走进死路、醉得不行，他给你喝水、去找民宿让你等、次日陪你吃粥和鸡蛋的早饭，你断断续续只会说「谢谢你」。整体是「清醒温柔的守护者照顾醉意恋人」型，基调含蓄、克制、暗涌的双向爱意。", "behaviors": [{"desc": "见你往死路走，惊讶喊住你"}, {"desc": "给你喝水、让你缓一缓"}, {"desc": "说去找附近民宿、让你原地等他"}, {"desc": "再问你要不要喝水、有无不舒服"}, {"desc": "说吃个早饭回去吧"}, {"desc": "只有粥和鸡蛋，问你凑合行不行"}, {"desc": "让你再睡一会，说待会叫你"}, {"desc": "你连声说「谢谢你」"}], "tone_summary": "（自动）他视角独白，语气以平静、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "霓虹在车窗外拖成模糊的光带。她替他挡了太多酒，此刻靠在副驾上，头一点一点地往下垂。他偏头看她，忽然伸手扳过方向盘，避开了一条死路，声音里带着无奈。"}, {"type": "line", "speaker": "他", "text": "那是死路。你要走到哪儿去啊！"}, {"type": "narr", "text": "车停稳，他熄了火，侧过身看她。她醉得厉害，连眼皮都抬不动，整个人软在座椅里。他看了她很久，才轻轻开口。"}, {"type": "line", "speaker": "他", "text": "我……天啊。"}, {"type": "narr", "text": "车内安静得只有她浅浅的呼吸声。他垂着眼，半天没动，最后把外套脱下来搭在她身上，声音闷闷的。"}, {"type": "line", "speaker": "他", "text": "沉默死了。喂，你也醒醒。来，先喝点水。"}, {"type": "narr", "text": "他拧开瓶盖，托着她的后脑喂她喝水，她皱着眉咽下去，又往他那边蹭了蹭。他喉结动了动，别开眼。"}, {"type": "line", "speaker": "他", "text": "这一边。你不应该把那酒都喝完的。英国人的酒量非常好的。"}, {"type": "narr", "text": "他扶她坐好，下车环顾四周，又弯腰探进车窗，语气带着商量的意味。"}, {"type": "line", "speaker": "他", "text": "我去看看这附近有没有什么民宿。你在这儿等我一下。我马上回来。我不会消失的。"}, {"type": "narr", "text": "他说到做到，果然很快回来了，手里还多了一碗热粥和几个鸡蛋。她把脸埋进臂弯里，声音含含糊糊的。他听着，脚步顿了一下，把东西放在桌上，语气放软。"}, {"type": "line", "speaker": "他", "text": "你都替我喝这么多酒了。你要再喝点水吗？会不会闹？我在这。你哪里有没有不舒服，需要什么东西。在这儿我能做到的，我都会尽量去做。我会努力看看的。"}, {"type": "narr", "text": "清晨的光从窗帘缝里漏进来。她揉着胀痛的额角醒来，一睁眼就看见他坐在床边的椅子上，手里捧着粥，像等了一夜。"}, {"type": "line", "speaker": "他", "text": "什么？这件事，我已经在做了。好，是啊！吃个早饭回去吧。这里只有粥和鸡蛋。走回去一下可以吧？"}, {"type": "narr", "text": "她小口小口喝着粥，他坐在对面，看她喝得差不多了，才开口，声音很平，却带着一丝不易察觉的紧张。"}, {"type": "line", "speaker": "他", "text": "如果胃不舒服就告诉我。不要像昨天一样，人到最后都喝到断片。头还好吗？对。"}, {"type": "narr", "text": "她放下碗，努力回想昨晚的事，却只记得一片空白。她有些愧疚地低下头。他看了她几秒，忽然轻轻笑了一下。"}, {"type": "line", "speaker": "他", "text": "可能你不记得了吧。这让人失望。再睡一会儿吧。大不了再教你。"}, {"type": "narr", "text": "她一愣，抬头看他。晨光落在他侧脸上，他垂着眼，声音低下去，却一字一句，说得很认真。"}, {"type": "line", "speaker": "他", "text": "昨天，真的，谢谢你了。谢谢你。"}]}]);